    var p=line.split('::');var n=(p.shift()||'').trim();var d=p.join('::').trim();
    if(n)out[n]={"Tên":n,"Mô_tả":d||'Do người chơi định nghĩa',"Nguồn":"Thiết lập khởi đầu","Trạng_thái":"Đang có"};
  });return out;
}
function parseLineage(txt){
