  var o={};o[n]={"Tên":n,"Nguồn":p[1]||'Thiết lập khởi đầu',"Mô_tả":p.slice(2).join(' :: ')||p[1]||'Do người chơi định nghĩa',"Trạng_thái":"Ổn định"};return o;
